screenPanels.initJs:
function(container, apiUrl, tables) {
  let currentMembers = [];
  let editingProjectId = null;

  // 1. 再描画関数の定義
  function renderProjects(projects) {
    const tbody = container.querySelector("#project-list-tbody");
    tbody.innerHTML = projects.map(project => {
      const statusClass = {
        '計画中': 'status-planning',
        '進行中': 'status-active', 
        '完了': 'status-completed',
        '中断': 'status-paused'
      }[project.アクティブフラグ ? '進行中' : '完了'] || 'status-planning';

      return `
        <tr data-id="${project.id}">
          <td>${project.プロジェクト名 || ""}</td>
          <td class="muted">${(project.プロジェクト概要 || "").substring(0, 50)}${(project.プロジェクト概要 || "").length > 50 ? "..." : ""}</td>
          <td>${project.開始日 ? new Date(project.開始日).toLocaleDateString() : ""}</td>
          <td>${project.終了日 ? new Date(project.終了日).toLocaleDateString() : ""}</td>
          <td>${project.予算上限 ? project.予算上限.toLocaleString() + "円" : "未設定"}</td>
          <td><span class="status-badge ${statusClass}">${project.アクティブフラグ ? '進行中' : '完了'}</span></td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${project.id}">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${project.id}">削除</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  function renderEquipmentMatching(results) {
    const tbody = container.querySelector("#matching-results-tbody");
    tbody.innerHTML = results.map(result => {
      const scoreClass = result.マッチング度スコア >= 80 ? 'high' : result.マッチング度スコア >= 60 ? 'medium' : 'low';
      return `
        <tr data-id="${result.id}">
          <td>${result.機器名 || ""}</td>
          <td><span class="matching-score ${scoreClass}">${result.マッチング度スコア || 0}%</span></td>
          <td class="muted">${result.推奨理由 || ""}</td>
          <td>${result.設置場所 || ""}</td>
          <td>${result.利用可能フラグ ? "利用可能" : "利用不可"}</td>
          <td>
            <button class="action-btn secondary">予約</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  function renderReservedEquipment(reservations) {
    const tbody = container.querySelector("#reserved-equipment-tbody");
    tbody.innerHTML = reservations.map(reservation => `
      <tr data-id="${reservation.id}">
        <td>${reservation.機器名 || ""}</td>
        <td>${reservation.ユーザー名 || ""}</td>
        <td>${reservation.使用開始日時 ? new Date(reservation.使用開始日時).toLocaleString() : ""}</td>
        <td>${reservation.返却予定日 ? new Date(reservation.返却予定日).toLocaleString() : ""}</td>
        <td><span class="status-badge">${reservation.稼働ステータス || ""}</span></td>
        <td>${reservation.プロジェクト名 || ""}</td>
      </tr>
    `).join("");
  }

  function showError(fieldId, message) {
    const errorElement = container.querySelector(`#error-${fieldId}`);
    if (errorElement) {
      errorElement.textContent = message;
      errorElement.classList.remove("hidden");
    }
  }

  function hideError(fieldId) {
    const errorElement = container.querySelector(`#error-${fieldId}`);
    if (errorElement) {
      errorElement.classList.add("hidden");
    }
  }

  function clearAllErrors() {
    const errorElements = container.querySelectorAll(".error-message");
    errorElements.forEach(el => el.classList.add("hidden"));
  }

  function validateForm() {
    let isValid = true;
    clearAllErrors();

    const projectName = container.querySelector("#input-project-name").value.trim();
    const projectOverview = container.querySelector("#input-project-overview").value.trim();
    const startDate = container.querySelector("#input-project-start").value;
    const endDate = container.querySelector("#input-project-end").value;
    const budget = container.querySelector("#input-project-budget").value;

    if (!projectName) {
      showError("project-name", "プロジェクト名は必須項目です");
      isValid = false;
    }

    if (!projectOverview) {
      showError("project-overview", "研究目的は必須項目です");
      isValid = false;
    }

    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError("project-start", "開始日は終了日より前の日付を入力してください");
      isValid = false;
    }

    if (budget && isNaN(Number(budget))) {
      showError("project-budget", "数値を入力してください");
      isValid = false;
    }

    return isValid;
  }

  function addMember(memberId) {
    if (memberId && !currentMembers.includes(memberId)) {
      currentMembers.push(memberId);
      renderMemberList();
    }
  }

  function removeMember(memberId) {
    currentMembers = currentMembers.filter(id => id !== memberId);
    renderMemberList();
  }

  function renderMemberList() {
    const memberList = container.querySelector("#member-list");
    memberList.innerHTML = currentMembers.map(member => `
      <div class="member-tag">
        ${member}
        <button type="button" class="remove-member" data-member="${member}">×</button>
      </div>
    `).join("");
  }

  function exportCSV() {
    window.aivicApi.list(0).then(projects => {
      if (!projects) return;

      const headers = ["プロジェクト名", "プロジェクト概要", "開始日", "終了日", "予算上限", "アクティブフラグ"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...projects.map(project => [
          `"${(project.プロジェクト名 || "").replace(/"/g, '""')}"`,
          `"${(project.プロジェクト概要 || "").replace(/"/g, '""')}"`,
          project.開始日 || "",
          project.終了日 || "",
          project.予算上限 || "",
          project.アクティブフラグ ? "true" : "false"
        ].join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "projects_export.csv";
      link.click();
    });
  }

  // 2. 初期データの描画
  renderProjects(tables[0].records || []);
  renderReservedEquipment(tables[2]?.records || []);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.trim();
    const status = container.querySelector("#select-status").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;

    const projects = await window.aivicApi.list(0);
    if (!projects) return;

    const filtered = projects.filter(project => {
      let matches = true;

      if (keyword) {
        matches = matches && JSON.stringify(project).toLowerCase().includes(keyword.toLowerCase());
      }

      if (status) {
        const projectStatus = project.アクティブフラグ ? '進行中' : '完了';
        matches = matches && projectStatus === status;
      }

      if (startDate) {
        matches = matches && project.開始日 && new Date(project.開始日) >= new Date(startDate);
      }

      if (endDate) {
        matches = matches && project.終了日 && new Date(project.終了日) <= new Date(endDate);
      }

      return matches;
    });

    renderProjects(filtered);
  });

  // クリアフィルターボタン
  container.querySelector("#btn-clear-filter").addEventListener("click", async () => {
    container.querySelector("#input-search").value = "";
    container.querySelector("#select-status").value = "";
    container.querySelector("#input-start-date").value = "";
    container.querySelector("#input-end-date").value = "";

    const projects = await window.aivicApi.list(0);
    if (projects) renderProjects(projects);
  });

  // 4. 新規プロジェクト登録ボタン
  container.querySelector("#btn-new-project").addEventListener("click", () => {
    editingProjectId = null;
    currentMembers = [];
    container.querySelector("#new-project-form").classList.remove("hidden");
    container.querySelector("#input-project-name").value = "";
    container.querySelector("#input-project-overview").value = "";
    container.querySelector("#input-project-start").value = "";
    container.querySelector("#input-project-end").value = "";
    container.querySelector("#input-project-budget").value = "";
    container.querySelector("#select-project-status").value = "計画中";
    container.querySelector("#input-equipment-requirements").value = "";
    renderMemberList();
    clearAllErrors();
  });

  // 予算分析ボタン
  container.querySelector("#btn-budget-analysis").addEventListener("click", () => {
    window.showScreen("scr-1778141651588");
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // キャンセルボタン
  container.querySelector("#btn-cancel-project").addEventListener("click", () => {
    container.querySelector("#new-project-form").classList.add("hidden");
  });

  // メンバー追加ボタン
  container.querySelector("#btn-add-member").addEventListener("click", () => {
    const memberId = container.querySelector("#input-team-member").value.trim();
    if (memberId) {
      addMember(memberId);
      container.querySelector("#input-team-member").value = "";
    }
  });

  // 5. 登録ボタンのイベントリスナー
  container.querySelector("#btn-save-project").addEventListener("click", async () => {
    if (!validateForm()) return;

    const projectData = {
      プロジェクト名: container.querySelector("#input-project-name").value.trim(),
      プロジェクト概要: container.querySelector("#input-project-overview").value.trim(),
      開始日: container.querySelector("#input-project-start").value,
      終了日: container.querySelector("#input-project-end").value || null,
      予算上限: container.querySelector("#input-project-budget").value ? parseInt(container.querySelector("#input-project-budget").value) : null,
      アクティブフラグ: container.querySelector("#select-project-status").value === "進行中"
    };

    let result;
    if (editingProjectId) {
      result = await window.aivicApi.update(0, editingProjectId, projectData);
    } else {
      result = await window.aivicApi.save(0, projectData);
    }

    if (result) {
      container.querySelector("#new-project-form").classList.add("hidden");
      const projects = await window.aivicApi.list(0);
      if (projects) renderProjects(projects);

      // 成功メッセージ表示
      const message = editingProjectId ? "プロジェクトを更新しました" : "プロジェクトを登録しました";
      const notification = document.createElement("div");
      notification.textContent = message;
      notification.style.cssText = "position: fixed; top: 20px; right: 20px; background: #4caf50; color: white; padding: 12px 24px; border-radius: 4px; z-index: 1000;";
      document.body.appendChild(notification);
      setTimeout(() => notification.remove(), 3000);
    }
  });

  // 6. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このプロジェクトを削除しますか？")) return;

      const result = await window.aivicApi.delete(0, deleteBtn.dataset.id);
      if (result !== null) {
        const projects = await window.aivicApi.list(0);
        if (projects) renderProjects(projects);
      }
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const projects = await window.aivicApi.list(0);
      if (!projects) return;

      const project = projects.find(p => p.id === editBtn.dataset.id);
      if (project) {
        editingProjectId = project.id;
        container.querySelector("#input-project-name").value = project.プロジェクト名 || "";
        container.querySelector("#input-project-overview").value = project.プロジェクト概要 || "";
        container.querySelector("#input-project-start").value = project.開始日 ? project.開始日.split('T')[0] : "";
        container.querySelector("#input-project-end").value = project.終了日 ? project.終了日.split('T')[0] : "";
        container.querySelector("#input-project-budget").value = project.予算上限 || "";
        container.querySelector("#select-project-status").value = project.アクティブフラグ ? "進行中" : "完了";
        container.querySelector("#new-project-form").classList.remove("hidden");
        clearAllErrors();
      }
      return;
    }

    // メンバー削除ボタン
    const removeMemberBtn = e.target.closest(".remove-member");
    if (removeMemberBtn) {
      removeMember(removeMemberBtn.dataset.member);
      return;
    }
  });

  // 最新データの読み込み
  window.aivicApi.list(0).then(projects => {
    if (projects) renderProjects(projects);
  });

  window.aivicApi.list(2).then(reservations => {
    if (reservations) renderReservedEquipment(reservations);
  });
}

function(container, apiUrl, tables) {
  let equipmentData = [];
  let selectedEquipment = null;
  let currentBudget = 0;
  let priceUnit = 'hourly';

  // 機器テーブル再描画
  function renderEquipmentTable(data) {
    const tbody = container.querySelector('#equipment-table');
    const priceHeader = container.querySelector('#price-header');
    priceHeader.textContent = priceUnit === 'hourly' ? '時間単価（円）' : '日単価（円）';

    tbody.innerHTML = data.map(equipment => {
      const pricing = equipment.pricing || { hourly: 1000, daily: 8000 };
      const price = priceUnit === 'hourly' ? pricing.hourly : pricing.daily;
      const isAvailable = equipment.利用可能フラグ;

      return `
        <tr data-id="${equipment.機器ID}">
          <td>${equipment.機器名 || ''}</td>
          <td>${equipment.設置場所 || ''}</td>
          <td>${price.toLocaleString()}</td>
          <td>
            <span style="padding: 4px 8px; border-radius: 4px; background: ${isAvailable ? '#28a745' : '#dc3545'}; color: #ffffff; font-size: 0.8em;">
              ${isAvailable ? '利用可能' : '利用不可'}
            </span>
          </td>
          <td>
            <input type="radio" name="selected-equipment" value="${equipment.機器ID}" ${!isAvailable ? 'disabled' : ''}>
          </td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${equipment.機器ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const equipments = await window.aivicApi.list(0);
      const pricings = await window.aivicApi.list(6);

      if (equipments && pricings) {
        equipmentData = equipments.map(eq => {
          const pricing = pricings.find(p => p.機器ID === eq.機器ID);
          return {
            ...eq,
            pricing: pricing ? {
              hourly: pricing.料金単位 === '時間単価' ? pricing.単価金額 : Math.round(pricing.単価金額 / 8),
              daily: pricing.料金単位 === '日単価' ? pricing.単価金額 : pricing.単価金額 * 8
            } : { hourly: 1000, daily: 8000 }
          };
        });
      } else {
        equipmentData = (tables[0]?.records || []).map(eq => ({
          ...eq,
          pricing: { hourly: 1000, daily: 8000 }
        }));
      }

      renderEquipmentTable(equipmentData);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      equipmentData = (tables[0]?.records || []).map(eq => ({
        ...eq,
        pricing: { hourly: 1000, daily: 8000 }
      }));
      renderEquipmentTable(equipmentData);
    }
  }

  // 料金計算
  function calculateCost() {
    const budgetInput = container.querySelector('#budget-input');
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');

    // バリデーション
    if (!budgetInput.value) {
      showError('予算を入力してください');
      return;
    }

    const budget = parseFloat(budgetInput.value);
    if (budget < 0) {
      showError('予算は正の値を入力してください');
      return;
    }

    if (isNaN(budget)) {
      showError('予算は数値で入力してください');
      return;
    }

    if (!selectedEquipment) {
      showError('機器を選択してください');
      return;
    }

    if (!periodStart.value || !periodEnd.value) {
      showError('利用期間を設定してください');
      return;
    }

    const startDate = new Date(periodStart.value);
    const endDate = new Date(periodEnd.value);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (startDate < today || endDate < today) {
      showError('過去の日付は設定できません');
      return;
    }

    if (startDate >= endDate) {
      showError('無効な日程設定です。開始日は終了日より前の日付を設定してください。');
      return;
    }

    currentBudget = budget;

    // 期間計算
    const days = Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24));
    const equipment = equipmentData.find(eq => eq.機器ID === selectedEquipment);

    // 基本料金計算
    let baseCost = 0;
    if (priceUnit === 'hourly') {
      baseCost = equipment.pricing.hourly * days * 8; // 1日8時間想定
    } else {
      baseCost = equipment.pricing.daily * days;
    }

    // 割引計算
    let discountRate = 0;
    if (container.querySelector('#discount-student').checked) discountRate += 0.1;
    if (container.querySelector('#discount-longterm').checked) discountRate += 0.15;
    if (container.querySelector('#discount-project').checked) discountRate += 0.05;

    const discountAmount = Math.floor(baseCost * discountRate);

    // 追加オプション計算
    let optionCost = 0;
    if (container.querySelector('#option-support').checked) optionCost += 5000;
    if (container.querySelector('#option-extend').checked) optionCost += 3000;
    if (container.querySelector('#option-material').checked) optionCost += 2000;

    const totalCost = baseCost - discountAmount + optionCost;
    const remaining = budget - totalCost;

    // 結果表示
    container.querySelector('#base-cost').textContent = baseCost.toLocaleString();
    container.querySelector('#discount-amount').textContent = discountAmount.toLocaleString();
    container.querySelector('#option-cost').textContent = optionCost.toLocaleString();
    container.querySelector('#total-cost').textContent = totalCost.toLocaleString();
    container.querySelector('#budget-remaining').textContent = remaining.toLocaleString();

    // 予算超過アラート
    const alertDiv = container.querySelector('#budget-alert');
    const alertMessage = container.querySelector('#alert-message');

    if (totalCost > budget) {
      alertDiv.classList.remove('hidden');
      alertMessage.textContent = `予算を${(totalCost - budget).toLocaleString()}円超過しています。`;
    } else {
      alertDiv.classList.add('hidden');
    }

    // グラフ描画
    drawSimulationChart(baseCost, discountAmount, optionCost, totalCost);

    // コストパフォーマンス評価
    updatePerformanceMetrics(equipment, totalCost, days);
  }

  // エラー表示
  function showError(message) {
    const alertDiv = container.querySelector('#budget-alert');
    const alertMessage = container.querySelector('#alert-message');
    alertDiv.classList.remove('hidden');
    alertMessage.textContent = message;
  }

  // グラフ描画
  function drawSimulationChart(baseCost, discountAmount, optionCost, totalCost) {
    const canvas = container.querySelector('#simulation-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const barWidth = 80;
    const barSpacing = 100;
    const startX = 50;
    const maxHeight = 300;
    const maxValue = Math.max(baseCost, totalCost) * 1.1;

    // 基本料金バー
    const baseHeight = (baseCost / maxValue) * maxHeight;
    ctx.fillStyle = '#007bff';
    ctx.fillRect(startX, canvas.height - 50 - baseHeight, barWidth, baseHeight);
    ctx.fillStyle = '#333333';
    ctx.fillText('基本料金', startX, canvas.height - 30);
    ctx.fillText(`¥${baseCost.toLocaleString()}`, startX, canvas.height - 15);

    // 割引額バー
    const discountHeight = (discountAmount / maxValue) * maxHeight;
    ctx.fillStyle = '#28a745';
    ctx.fillRect(startX + barSpacing, canvas.height - 50 - discountHeight, barWidth, discountHeight);
    ctx.fillStyle = '#333333';
    ctx.fillText('割引額', startX + barSpacing, canvas.height - 30);
    ctx.fillText(`¥${discountAmount.toLocaleString()}`, startX + barSpacing, canvas.height - 15);

    // オプション料金バー
    const optionHeight = (optionCost / maxValue) * maxHeight;
    ctx.fillStyle = '#ffc107';
    ctx.fillRect(startX + barSpacing * 2, canvas.height - 50 - optionHeight, barWidth, optionHeight);
    ctx.fillStyle = '#333333';
    ctx.fillText('オプション', startX + barSpacing * 2, canvas.height - 30);
    ctx.fillText(`¥${optionCost.toLocaleString()}`, startX + barSpacing * 2, canvas.height - 15);

    // 合計料金バー
    const totalHeight = (totalCost / maxValue) * maxHeight;
    ctx.fillStyle = '#dc3545';
    ctx.fillRect(startX + barSpacing * 3, canvas.height - 50 - totalHeight, barWidth, totalHeight);
    ctx.fillStyle = '#333333';
    ctx.fillText('合計料金', startX + barSpacing * 3, canvas.height - 30);
    ctx.fillText(`¥${totalCost.toLocaleString()}`, startX + barSpacing * 3, canvas.height - 15);
  }

  // コストパフォーマンス評価更新
  function updatePerformanceMetrics(equipment, totalCost, days) {
    const metricsDiv = container.querySelector('#performance-metrics');
    const dailyCost = Math.round(totalCost / days);
    const efficiency = equipment.pricing ? Math.round((equipment.pricing.daily / dailyCost) * 100) : 100;

    metricsDiv.innerHTML = `
      <div style="padding: 15px; border: 1px solid var(--border); border-radius: 4px;">
        <h4>日割り単価</h4>
        <div style="font-size: 1.2em; font-weight: bold; color: var(--text);">¥${dailyCost.toLocaleString()}</div>
      </div>
      <div style="padding: 15px; border: 1px solid var(--border); border-radius: 4px;">
        <h4>コスト効率</h4>
        <div style="font-size: 1.2em; font-weight: bold; color: var(--text);">${efficiency}%</div>
      </div>
      <div style="padding: 15px; border: 1px solid var(--border); border-radius: 4px;">
        <h4>利用期間</h4>
        <div style="font-size: 1.2em; font-weight: bold; color: var(--text);">${days}日</div>
      </div>
    `;
  }

  // 料金詳細ポップアップ表示
  function showDetailPopup(equipmentId) {
    const equipment = equipmentData.find(eq => eq.機器ID === equipmentId);
    if (!equipment) return;

    const popup = container.querySelector('#detail-popup');
    const content = container.querySelector('#detail-content');

    content.innerHTML = `
      <h4>${equipment.機器名}</h4>
      <div style="margin: 15px 0;">
        <strong>設置場所:</strong> ${equipment.設置場所 || '-'}<br>
        <strong>メーカー:</strong> ${equipment.メーカー || '-'}<br>
        <strong>管理者:</strong> ${equipment.管理者 || '-'}
      </div>
      <div style="margin: 15px 0;">
        <h5>料金体系</h5>
        <div>時間単価: ¥${equipment.pricing.hourly.toLocaleString()}</div>
        <div>日単価: ¥${equipment.pricing.daily.toLocaleString()}</div>
      </div>
      <div style="margin: 15px 0;">
        <strong>機器説明:</strong><br>
        ${equipment.機器説明 || '詳細情報なし'}
      </div>
    `;

    popup.classList.remove('hidden');
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['機器名', '設置場所', '時間単価', '日単価', '利用可能'];
    const rows = equipmentData.map(eq => [
      eq.機器名 || '',
      eq.設置場所 || '',
      eq.pricing.hourly,
      eq.pricing.daily,
      eq.利用可能フラグ ? '利用可能' : '利用不可'
    ]);

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'equipment_pricing.csv';
    a.click();
    URL.revokeObjectURL(url);
  }

  // イベントリスナー設定
  container.querySelector('#btn-calculate').addEventListener('click', calculateCost);

  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1778141874805');
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-close-popup').addEventListener('click', () => {
    container.querySelector('#detail-popup').classList.add('hidden');
  });

  // 単価切り替え
  container.querySelectorAll('input[name="price-unit"]').forEach(radio => {
    radio.addEventListener('change', (e) => {
      priceUnit = e.target.value;
      renderEquipmentTable(equipmentData);
    });
  });

  // 機器選択
  container.addEventListener('change', (e) => {
    if (e.target.name === 'selected-equipment') {
      selectedEquipment = e.target.value;
    }
  });

  // 予算内フィルター
  container.querySelector('#btn-apply-filter').addEventListener('click', () => {
    const filterBudget = container.querySelector('#filter-budget').checked;
    const budgetValue = parseFloat(container.querySelector('#budget-input').value) || 0;

    let filteredData = equipmentData;
    if (filterBudget && budgetValue > 0) {
      filteredData = equipmentData.filter(eq => {
        const price = priceUnit === 'hourly' ? eq.pricing.hourly : eq.pricing.daily;
        return price <= budgetValue;
      });
    }

    renderEquipmentTable(filteredData);
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetailPopup(detailBtn.dataset.id);
    }
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  let allEquipmentData = [];
  let allStatusData = [];
  let currentSelectedEquipmentId = null;

  // 機器稼働状況テーブルのインデックス
  const EQUIPMENT_TABLE_INDEX = 0; // 研究機器マスタ
  const STATUS_TABLE_INDEX = 2; // 機器稼働状況

  // ステータスバッジのスタイルを取得
  function getStatusBadgeStyle(status) {
    const styles = {
      '稼働中': 'background: #22c55e; color: #ffffff; padding: 4px 8px; border-radius: 4px; font-size: 12px;',
      '停止中': 'background: #6b7280; color: #ffffff; padding: 4px 8px; border-radius: 4px; font-size: 12px;',
      'メンテナンス中': 'background: #f59e0b; color: #ffffff; padding: 4px 8px; border-radius: 4px; font-size: 12px;',
      '故障中': 'background: #ef4444; color: #ffffff; padding: 4px 8px; border-radius: 4px; font-size: 12px;'
    };
    return styles[status] || 'background: #6b7280; color: #ffffff; padding: 4px 8px; border-radius: 4px; font-size: 12px;';
  }

  // 時間フォーマット関数
  function formatDuration(minutes) {
    if (!minutes) return '0時間0分';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins}分`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateTime) {
    if (!dateTime) return '-';
    const date = new Date(dateTime);
    return date.toLocaleString('ja-JP', {
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // サマリー更新
  function updateSummary(statusData) {
    const summary = {
      '稼働中': 0,
      '停止中': 0,
      'メンテナンス中': 0,
      '故障中': 0
    };

    statusData.forEach(status => {
      if (summary.hasOwnProperty(status.稼働ステータス)) {
        summary[status.稼働ステータス]++;
      }
    });

    container.querySelector('#summary-running').textContent = summary['稼働中'];
    container.querySelector('#summary-stopped').textContent = summary['停止中'];
    container.querySelector('#summary-maintenance').textContent = summary['メンテナンス中'];
    container.querySelector('#summary-error').textContent = summary['故障中'];
  }

  // 機器一覧の再描画
  function renderEquipmentList(equipmentData, statusData) {
    const tbody = container.querySelector('#equipment-list');
    const noDataMessage = container.querySelector('#no-data-message');

    if (!equipmentData || equipmentData.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.classList.remove('hidden');
      return;
    }

    noDataMessage.classList.add('hidden');

    // 機器データと稼働状況データを結合
    const combinedData = equipmentData.map(equipment => {
      const status = statusData.find(s => s.機器ID === equipment.id) || {};
      return { ...equipment, ...status };
    });

    tbody.innerHTML = combinedData.map(item => `
      <tr data-id="${item.id}">
        <td>${item.機器名 || ''}</td>
        <td>${item.id || ''}</td>
        <td>${item.設置場所 || ''}</td>
        <td><span style="${getStatusBadgeStyle(item.稼働ステータス || '停止中')}">${item.稼働ステータス || '停止中'}</span></td>
        <td>${item.ユーザーID || '-'}</td>
        <td>${formatDateTime(item.使用開始日時)}</td>
        <td>${formatDateTime(item.返却予定日)}</td>
        <td>${formatDuration(item.累積稼働時間)}</td>
        <td>${item.メンテナンス必要フラグ ? '要メンテナンス' : '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${item.id}">詳細</button>
          ${item.稼働ステータス === '稼働中' ? `<button class="action-btn emergency-stop-btn" data-id="${item.id}" style="background: #ef4444; color: #ffffff; margin-left: 4px;">緊急停止</button>` : ''}
        </td>
      </tr>
    `).join('');

    updateSummary(statusData);
  }

  // フィルタリング処理
  function applyFilters() {
    const statusFilter = container.querySelector('#filter-status').value;
    const categoryFilter = container.querySelector('#filter-category').value;
    const searchKeyword = container.querySelector('#search-equipment').value.toLowerCase();

    let filteredEquipment = [...allEquipmentData];
    let filteredStatus = [...allStatusData];

    // 機器名検索
    if (searchKeyword) {
      filteredEquipment = filteredEquipment.filter(item => 
        (item.機器名 || '').toLowerCase().includes(searchKeyword)
      );
    }

    // カテゴリーフィルター（機器説明に含まれると仮定）
    if (categoryFilter) {
      filteredEquipment = filteredEquipment.filter(item => 
        (item.機器説明 || '').includes(categoryFilter)
      );
    }

    // 稼働状況フィルター
    if (statusFilter) {
      const equipmentIds = filteredStatus
        .filter(status => status.稼働ステータス === statusFilter)
        .map(status => status.機器ID);
      filteredEquipment = filteredEquipment.filter(item => equipmentIds.includes(item.id));
      filteredStatus = filteredStatus.filter(status => status.稼働ステータス === statusFilter);
    } else {
      // 機器IDでフィルタリングされた稼働状況データを取得
      const equipmentIds = filteredEquipment.map(item => item.id);
      filteredStatus = filteredStatus.filter(status => equipmentIds.includes(status.機器ID));
    }

    renderEquipmentList(filteredEquipment, filteredStatus);
  }

  // 機器詳細モーダル表示
  function showEquipmentDetail(equipmentId) {
    const equipment = allEquipmentData.find(item => item.id === equipmentId);
    const status = allStatusData.find(item => item.機器ID === equipmentId);

    if (!equipment) return;

    currentSelectedEquipmentId = equipmentId;

    const modal = container.querySelector('#equipment-detail-modal');
    const modalName = container.querySelector('#modal-equipment-name');
    const modalContent = container.querySelector('#modal-content');

    modalName.textContent = equipment.機器名 || '機器詳細';

    modalContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 24px;">
        <div>
          <h4 style="color: var(--text); margin-bottom: 16px;">基本情報</h4>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">機器ID:</strong> ${equipment.id || '-'}
          </div>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">機器名:</strong> ${equipment.機器名 || '-'}
          </div>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">設置場所:</strong> ${equipment.設置場所 || '-'}
          </div>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">メーカー:</strong> ${equipment.メーカー || '-'}
          </div>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">管理者:</strong> ${equipment.管理者 || '-'}
          </div>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">導入時期:</strong> ${equipment.導入時期 || '-'}
          </div>
        </div>
        <div>
          <h4 style="color: var(--text); margin-bottom: 16px;">稼働状況</h4>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">現在の状態:</strong> 
            <span style="${getStatusBadgeStyle(status?.稼働ステータス || '停止中')}">${status?.稼働ステータス || '停止中'}</span>
          </div>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">現在利用者:</strong> ${status?.ユーザーID || '-'}
          </div>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">利用開始:</strong> ${formatDateTime(status?.使用開始日時)}
          </div>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">返却予定:</strong> ${formatDateTime(status?.返却予定日)}
          </div>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">累積稼働時間:</strong> ${formatDuration(status?.累積稼働時間)}
          </div>
          <div style="margin-bottom: 12px;">
            <strong style="color: var(--text);">メンテナンス:</strong> ${status?.メンテナンス必要フラグ ? '要メンテナンス' : '正常'}
          </div>
        </div>
      </div>
      ${equipment.機器説明 ? `
        <div style="margin-top: 24px;">
          <h4 style="color: var(--text); margin-bottom: 16px;">機器説明</h4>
          <p style="color: var(--text); line-height: 1.6;">${equipment.機器説明}</p>
        </div>
      ` : ''}
    `;

    modal.classList.remove('hidden');
  }

  // 予約スケジュール描画
  function renderSchedule(date) {
    const scheduleGrid = container.querySelector('#schedule-grid');

    // 時間軸（8:00-18:00）
    const hours = [];
    for (let i = 8; i <= 18; i++) {
      hours.push(`${i}:00`);
    }

    // 稼働中の機器を取得
    const runningEquipment = allEquipmentData.filter(equipment => {
      const status = allStatusData.find(s => s.機器ID === equipment.id);
      return status && status.稼働ステータス === '稼働中';
    });

    scheduleGrid.innerHTML = `
      <div style="display: grid; grid-template-columns: 150px repeat(${hours.length}, 1fr); gap: 1px; background: var(--border);">
        <div style="background: var(--bg-card); padding: 8px; font-weight: bold; color: var(--text);">機器名</div>
        ${hours.map(hour => `<div style="background: var(--bg-card); padding: 8px; text-align: center; font-size: 12px; color: var(--text);">${hour}</div>`).join('')}

        ${runningEquipment.map(equipment => {
          const status = allStatusData.find(s => s.機器ID === equipment.id);
          return `
            <div style="background: var(--bg-card); padding: 8px; color: var(--text); font-size: 14px;">${equipment.機器名}</div>
            ${hours.map(hour => {
              const isUsed = status && status.使用開始日時 && status.返却予定日;
              return `<div style="background: ${isUsed ? '#22c55e' : 'var(--bg-card)'}; padding: 8px; border-radius: 2px;"></div>`;
            }).join('')}
          `;
        }).join('')}
      </div>
    `;
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['機器名', '機器ID', '設置場所', '稼働状況', '現在利用者', '利用開始時刻', '返却予定', '累積稼働時間', 'メンテナンス予定'];

    const combinedData = allEquipmentData.map(equipment => {
      const status = allStatusData.find(s => s.機器ID === equipment.id) || {};
      return {
        機器名: equipment.機器名 || '',
        機器ID: equipment.id || '',
        設置場所: equipment.設置場所 || '',
        稼働状況: status.稼働ステータス || '停止中',
        現在利用者: status.ユーザーID || '',
        利用開始時刻: formatDateTime(status.使用開始日時),
        返却予定: formatDateTime(status.返却予定日),
        累積稼働時間: formatDuration(status.累積稼働時間),
        メンテナンス予定: status.メンテナンス必要フラグ ? '要メンテナンス' : ''
      };
    });

    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...combinedData.map(row => 
        headers.map(header => {
          const value = row[header] || '';
          return value.includes(',') ? `"${value}"` : value;
        }).join(',')
      )
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `機器稼働状況_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 緊急停止処理
  async function emergencyStop(equipmentId) {
    if (!confirm('機器を緊急停止しますか？')) return;

    try {
      const status = allStatusData.find(s => s.機器ID === equipmentId);
      if (status) {
        const updated = await window.aivicApi.update(STATUS_TABLE_INDEX, status.id, {
          稼働ステータス: '停止中',
          返却日時: new Date().toISOString(),
          ユーザーID: null
        });

        if (updated) {
          // データを再読み込み
          const [equipmentData, statusData] = await Promise.all([
            window.aivicApi.list(EQUIPMENT_TABLE_INDEX),
            window.aivicApi.list(STATUS_TABLE_INDEX)
          ]);

          if (equipmentData && statusData) {
            allEquipmentData = equipmentData;
            allStatusData = statusData;
            applyFilters();
            alert('機器を緊急停止しました。');
          }
        }
      }
    } catch (error) {
      alert('緊急停止に失敗しました。');
    }
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const [equipmentData, statusData] = await Promise.all([
        window.aivicApi.list(EQUIPMENT_TABLE_INDEX),
        window.aivicApi.list(STATUS_TABLE_INDEX)
      ]);

      if (equipmentData && statusData) {
        allEquipmentData = equipmentData;
        allStatusData = statusData;
        renderEquipmentList(allEquipmentData, allStatusData);
      } else {
        // APIが利用できない場合は初期データを使用
        allEquipmentData = tables[EQUIPMENT_TABLE_INDEX]?.records || [];
        allStatusData = tables[STATUS_TABLE_INDEX]?.records || [];
        renderEquipmentList(allEquipmentData, allStatusData);
      }
    } catch (error) {
      // エラー時は初期データを使用
      allEquipmentData = tables[EQUIPMENT_TABLE_INDEX]?.records || [];
      allStatusData = tables[STATUS_TABLE_INDEX]?.records || [];
      renderEquipmentList(allEquipmentData, allStatusData);
    }
  }

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#schedule-date').value = today;

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#filter-status').value = '';
    container.querySelector('#filter-category').value = '';
    container.querySelector('#search-equipment').value = '';
    renderEquipmentList(allEquipmentData, allStatusData);
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-equipment-search').addEventListener('click', () => {
    window.showScreen("scr-1778141842347");
  });

  container.querySelector('#schedule-date').addEventListener('change', (e) => {
    renderSchedule(e.target.value);
  });

  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#equipment-detail-modal').classList.add('hidden');
  });

  container.querySelector('#btn-emergency-stop').addEventListener('click', () => {
    if (currentSelectedEquipmentId) {
      emergencyStop(currentSelectedEquipmentId);
    }
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const emergencyBtn = e.target.closest('.emergency-stop-btn');

    if (detailBtn) {
      const equipmentId = detailBtn.dataset.id;
      showEquipmentDetail(equipmentId);
    }

    if (emergencyBtn) {
      const equipmentId = emergencyBtn.dataset.id;
      await emergencyStop(equipmentId);
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#equipment-detail-modal').addEventListener('click', (e) => {
    if (e.target.id === 'equipment-detail-modal') {
      container.querySelector('#equipment-detail-modal').classList.add('hidden');
    }
  });

  // 初期データ読み込み
  loadData();
  renderSchedule(today);
}

function(container, apiUrl, tables) {
  // 文字数カウンター機能
  function setupCharCounter(inputId, counterId, maxLength) {
    const input = container.querySelector(`#${inputId}`);
    const counter = container.querySelector(`#${counterId}`);
    if (input && counter) {
      input.addEventListener('input', () => {
        const currentLength = input.value.length;
        counter.textContent = currentLength;
        if (currentLength > maxLength) {
          input.value = input.value.substring(0, maxLength);
          counter.textContent = maxLength;
        }
      });
    }
  }

  // 文字数カウンター設定
  setupCharCounter('experiment-details', 'experiment-details-count', 2000);
  setupCharCounter('target-material', 'target-material-count', 200);
  setupCharCounter('special-requirements', 'special-requirements-count', 1000);

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  const startDateInput = container.querySelector('#start-date');
  const endDateInput = container.querySelector('#end-date');

  if (startDateInput) {
    startDateInput.min = today;
  }
  if (endDateInput) {
    endDateInput.min = today;
  }

  // 日付バリデーション
  function validateDates() {
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const startDateError = container.querySelector('#start-date-error');
    const endDateError = container.querySelector('#end-date-error');

    let isValid = true;

    if (startDate && startDate < today) {
      startDateError.textContent = '利用開始日は今日以降の日付を選択してください';
      startDateError.classList.remove('hidden');
      isValid = false;
    } else {
      startDateError.classList.add('hidden');
    }

    if (startDate && endDate && endDate < startDate) {
      endDateError.textContent = '利用終了日は開始日以降の日付を選択してください';
      endDateError.classList.remove('hidden');
      isValid = false;
    } else if (endDate && endDate < today) {
      endDateError.textContent = '利用終了日は今日以降の日付を選択してください';
      endDateError.classList.remove('hidden');
      isValid = false;
    } else {
      endDateError.classList.add('hidden');
    }

    return isValid;
  }

  startDateInput.addEventListener('change', validateDates);
  endDateInput.addEventListener('change', validateDates);

  // バリデーション関数
  function validateForm() {
    let isValid = true;
    const errors = [];

    // プロジェクト名
    const projectName = container.querySelector('#project-name').value.trim();
    const projectNameError = container.querySelector('#project-name-error');
    if (!projectName) {
      projectNameError.classList.remove('hidden');
      isValid = false;
    } else {
      projectNameError.classList.add('hidden');
    }

    // 研究目的
    const researchPurpose = container.querySelector('#research-purpose').value;
    const researchPurposeError = container.querySelector('#research-purpose-error');
    if (!researchPurpose) {
      researchPurposeError.classList.remove('hidden');
      isValid = false;
    } else {
      researchPurposeError.classList.add('hidden');
    }

    // 実験内容詳細
    const experimentDetails = container.querySelector('#experiment-details').value.trim();
    const experimentDetailsError = container.querySelector('#experiment-details-error');
    if (!experimentDetails) {
      experimentDetailsError.classList.remove('hidden');
      isValid = false;
    } else {
      experimentDetailsError.classList.add('hidden');
    }

    // 測定項目
    const measurementItems = container.querySelectorAll('.measurement-item:checked');
    const measurementItemsError = container.querySelector('#measurement-items-error');
    if (measurementItems.length === 0) {
      measurementItemsError.classList.remove('hidden');
      isValid = false;
    } else {
      measurementItemsError.classList.add('hidden');
    }

    // 利用期間
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const startDateError = container.querySelector('#start-date-error');
    const endDateError = container.querySelector('#end-date-error');

    if (!startDate) {
      startDateError.classList.remove('hidden');
      isValid = false;
    }
    if (!endDate) {
      endDateError.classList.remove('hidden');
      isValid = false;
    }

    // 利用時間帯
    const timeSlot = container.querySelector('input[name="time-slot"]:checked');
    const timeSlotError = container.querySelector('#time-slot-error');
    if (!timeSlot) {
      timeSlotError.classList.remove('hidden');
      isValid = false;
    } else {
      timeSlotError.classList.add('hidden');
    }

    // 日付バリデーション
    if (startDate && endDate) {
      isValid = validateDates() && isValid;
    }

    // 数値バリデーション
    const measurementAccuracy = container.querySelector('#measurement-accuracy').value;
    const sampleCount = container.querySelector('#sample-count').value;
    const budgetLimit = container.querySelector('#budget-limit').value;

    if (measurementAccuracy && parseFloat(measurementAccuracy) < 0) {
      alert('測定精度は0以上の値を入力してください');
      isValid = false;
    }
    if (sampleCount && parseInt(sampleCount) < 0) {
      alert('サンプル数は0以上の値を入力してください');
      isValid = false;
    }
    if (budgetLimit && parseInt(budgetLimit) < 0) {
      alert('予算上限は0以上の値を入力してください');
      isValid = false;
    }

    return isValid;
  }

  // 検索結果表示関数
  function renderSearchResults(matchingResults) {
    const tbody = container.querySelector('#search-results-tbody');
    const searchResults = container.querySelector('#search-results');

    if (!matchingResults || matchingResults.length === 0) {
      searchResults.classList.add('hidden');
      alert('条件に合致する機器が見つかりませんでした。');
      return;
    }

    tbody.innerHTML = matchingResults.map(result => `
      <tr data-id="${result.id}">
        <td>${result.機器名 || ''}</td>
        <td>${result.設置場所 || ''}</td>
        <td>
          <span style="background: ${result.マッチング度スコア >= 80 ? '#27ae60' : result.マッチング度スコア >= 60 ? '#f39c12' : '#e74c3c'}; color: #ffffff; padding: 4px 8px; border-radius: 12px; font-size: 12px;">
            ${result.マッチング度スコア || 0}%
          </span>
        </td>
        <td>${result.推奨理由 || ''}</td>
        <td>
          <span style="background: #27ae60; color: #ffffff; padding: 4px 8px; border-radius: 12px; font-size: 12px;">
            利用可能
          </span>
        </td>
        <td>
          <button class="action-btn secondary" onclick="alert('機器詳細画面への遷移機能は今後実装予定です')">詳細</button>
        </td>
      </tr>
    `).join('');

    searchResults.classList.remove('hidden');
  }

  // 機器候補検索ボタン
  container.querySelector('#btn-search-equipment').addEventListener('click', async () => {
    if (!validateForm()) {
      return;
    }

    const searchBtn = container.querySelector('#btn-search-equipment');
    searchBtn.disabled = true;
    searchBtn.textContent = '検索中...';

    try {
      // 研究目的・実験内容を保存
      const researchData = {
        研究目的名: container.querySelector('#research-purpose').value,
        実験内容詳細: container.querySelector('#experiment-details').value,
        安全性確認済フラグ: false,
        承認状態: 0
      };

      const savedResearch = await window.aivicApi.save(3, researchData);

      if (savedResearch) {
        // 機器候補マッチング結果を生成（模擬データ）
        const equipmentList = await window.aivicApi.list(0);
        if (equipmentList && equipmentList.length > 0) {
          const sessionId = 'search_' + Date.now();
          const matchingResults = [];

          // 選択された測定項目を取得
          const selectedItems = Array.from(container.querySelectorAll('.measurement-item:checked')).map(cb => cb.value);

          equipmentList.forEach((equipment, index) => {
            if (equipment.利用可能フラグ) {
              // マッチング度を計算（簡易版）
              let score = 50; // 基本スコア

              // 測定項目との適合性をチェック
              selectedItems.forEach(item => {
                if (equipment.機器説明 && equipment.機器説明.includes(item.replace('測定', ''))) {
                  score += 10;
                }
              });

              // 最大100%に制限
              score = Math.min(score, 100);

              const matchingResult = {
                id: 'match_' + Date.now() + '_' + index,
                検索セッションID: sessionId,
                機器ID: equipment.機器ID,
                機器名: equipment.機器名,
                設置場所: equipment.設置場所,
                マッチング度スコア: score,
                推奨理由: `選択された測定項目「${selectedItems.join('、')}」に対応可能な機器です。`,
                マッチング実行日時: new Date().toISOString()
              };

              matchingResults.push(matchingResult);
            }
          });

          // マッチング度でソート
          matchingResults.sort((a, b) => b.マッチング度スコア - a.マッチング度スコア);

          // 上位5件を保存
          const topResults = matchingResults.slice(0, 5);
          for (const result of topResults) {
            await window.aivicApi.save(7, result);
          }

          renderSearchResults(topResults);
        } else {
          alert('利用可能な機器が登録されていません。');
        }
      }
    } catch (error) {
      console.error('検索エラー:', error);
      alert('検索中にエラーが発生しました。');
    } finally {
      searchBtn.disabled = false;
      searchBtn.textContent = '機器候補自動検索';
    }
  });

  // AI機器提案ボタン
  container.querySelector('#btn-ai-suggestion').addEventListener('click', () => {
    if (!validateForm()) {
      return;
    }
    window.showScreen("scr-1778141721002");
  });

  // 数値入力フィールドの負の値チェック
  const numericInputs = container.querySelectorAll('input[type="number"]');
  numericInputs.forEach(input => {
    input.addEventListener('input', (e) => {
      if (parseFloat(e.target.value) < 0) {
        e.target.value = '';
      }
    });
  });

  // 無効な文字入力チェック
  const textInputs = container.querySelectorAll('input[type="text"], textarea');
  textInputs.forEach(input => {
    input.addEventListener('input', (e) => {
      const value = e.target.value;
      // スクリプトタグや危険な文字列をチェック
      if (value.includes('<script>') || value.includes('</script>') || 
          value.includes('javascript:') || value.includes('onload=') ||
          value.includes('onerror=') || value.includes('onclick=')) {
        e.target.value = value.replace(/<script.*?>.*?<\/script>/gi, '')
                              .replace(/javascript:/gi, '')
                              .replace(/on\w+=/gi, '');
        alert('無効な文字が含まれています。入力内容を確認してください。');
      }
    });
  });

  // 初期データ読み込み
  window.aivicApi.list(0).then(equipmentList => {
    console.log('機器一覧を読み込みました:', equipmentList?.length || 0, '件');
  }).catch(error => {
    console.error('機器一覧の読み込みに失敗しました:', error);
  });
}

function(container, apiUrl, tables) {
