      <tr data-id="${r.id}" class="equipment-row" style="cursor: pointer;">
        <td>${r.機器名 || ''}</td>
        <td>${r.設置場所 || ''}</td>
        <td>${r.管理者 || ''}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; ${r.利用可能フラグ ? 'background: rgba(40, 167, 69, 0.1); color: #28a745;' : 'background: rgba(220, 53, 69, 0.1); color: #dc3545;'}">
            ${r.利用可能フラグ ? '利用可能' : '利用不可'}
