  // 機器詳細表示
  function showEquipmentDetail(equipmentId) {
    const equipment = equipmentData.find(e => e.id === equipmentId);
    const detailContainer = container.querySelector('#equipment-detail');

    if (!equipment) {
      detailContainer.innerHTML = '<p class="muted">機器情報が見つかりません</p>';
      return;
    }

    // 機器仕様詳細を取得
    window.aivicApi.list(1).then(specs => {
      const equipmentSpecs = specs.filter(s => s.機器ID === equipmentId);

      detailContainer.innerHTML = `
        <h4 style="margin: 0 0 12px 0; color: var(--text);">${equipment.機器名}</h4>
        <div style="margin-bottom: 12px;">
          <strong style="color: var(--text);">設置場所:</strong> <span style="color: var(--text);">${equipment.設置場所}</span>
        </div>
        <div style="margin-bottom: 12px;">
          <strong style="color: var(--text);">管理者:</strong> <span style="color: var(--text);">${equipment.管理者}</span>
        </div>
        <div style="margin-bottom: 12px;">
          <strong style="color: var(--text);">メーカー:</strong> <span style="color: var(--text);">${equipment.メーカー || '未設定'}</span>
        </div>
        ${equipment.機器説明 ? `<div style="margin-bottom: 12px;"><strong style="color: var(--text);">説明:</strong><br><span style="color: var(--text);">${equipment.機器説明}</span></div>` : ''}
        ${equipmentSpecs.length > 0 ? `
          <div style="margin-top: 16px;">
            <strong style="color: var(--text);">仕様詳細:</strong>
            <div style="margin-top: 8px;">
              ${equipmentSpecs.map(spec => `
                <div style="margin-bottom: 8px; padding: 8px; background: rgba(0, 102, 204, 0.05); border-radius: 4px;">
                  <strong style="color: var(--text);">${spec.仕様項目名}:</strong> <span style="color: var(--text);">${spec.仕様値}</span>
                  ${spec.必須確認項目 ? '<span style="color: #dc3545; font-size: 12px; margin-left: 8px;">※要確認</span>' : ''}
                </div>
              `).join('')}
            </div>
          </div>
        ` : ''}
      `;
    });
  }

  // カレンダー描画
  function renderCalendar() {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const startDate = new Date(firstDay);
    startDate.setDate(startDate.getDate() - firstDay.getDay());

    container.querySelector('#calendar-title').textContent = `${year}年${month + 1}月`;

    const grid = container.querySelector('#calendar-grid');
    grid.innerHTML = '';

    // 曜日ヘッダー
    ['日', '月', '火', '水', '木', '金', '土'].forEach(day => {
      const dayHeader = document.createElement('div');
      dayHeader.textContent = day;
      dayHeader.style.cssText = 'padding: 8px; text-align: center; font-weight: bold; color: var(--text); background: rgba(0, 102, 204, 0.1);';
      grid.appendChild(dayHeader);
    });

    // 日付セル
    for (let i = 0; i < 42; i++) {
      const cellDate = new Date(startDate);
      cellDate.setDate(startDate.getDate() + i);

      const dayCell = document.createElement('div');
      dayCell.textContent = cellDate.getDate();
      dayCell.dataset.date = cellDate.toISOString().split('T')[0];

      const isCurrentMonth = cellDate.getMonth() === month;
      const isToday = cellDate.toDateString() === new Date().toDateString();
      const isPast = cellDate < new Date().setHours(0, 0, 0, 0);

      dayCell.style.cssText = `
        padding: 8px; text-align: center; cursor: pointer; border: 1px solid var(--border);
        color: ${isCurrentMonth ? 'var(--text)' : 'var(--text-muted)'};
        background: ${isToday ? 'rgba(0, 102, 204, 0.2)' : 'var(--bg-card)'};
        ${isPast ? 'opacity: 0.5; cursor: not-allowed;' : ''}
      `;

      if (!isPast) {
        dayCell.addEventListener('click', () => {
          container.querySelectorAll('#calendar-grid > div').forEach(cell => {
            if (cell.dataset.date) {
              cell.style.background = isToday && cell.dataset.date === cellDate.toISOString().split('T')[0] ? 'rgba(0, 102, 204, 0.2)' : 'var(--bg-card)';
            }
          });
          dayCell.style.background = 'rgba(0, 102, 204, 0.4)';

          const startInput = container.querySelector('#start-datetime');
          if (startInput.value) {
            const currentTime = startInput.value.split('T')[1] || '09:00';
            startInput.value = `${cellDate.toISOString().split('T')[0]}T${currentTime}`;
          } else {
            startInput.value = `${cellDate.toISOString().split('T')[0]}T09:00`;
          }
          updateReservationSummary();
        });
      }

      grid.appendChild(dayCell);
    }
  }

  // 予約内容サマリー更新
  function updateReservationSummary() {
    const equipmentName = container.querySelector('#selected-equipment').value;
    const startDateTime = container.querySelector('#start-datetime').value;
    const endDateTime = container.querySelector('#end-datetime').value;
    const summaryContainer = container.querySelector('#reservation-summary');

    if (!equipmentName || !startDateTime || !endDateTime) {
      summaryContainer.innerHTML = '<p>機器・日時を選択すると予約内容が表示されます</p>';
      return;
    }

    const start = new Date(startDateTime);
    const end = new Date(endDateTime);
    const duration = Math.round((end - start) / (1000 * 60 * 60 * 100)) / 10;

    summaryContainer.innerHTML = `
      <div><strong>機器:</strong> ${equipmentName}</div>
      <div><strong>利用日時:</strong> ${start.toLocaleString('ja-JP')} ～ ${end.toLocaleString('ja-JP')}</div>
      <div><strong>利用時間:</strong> ${duration}時間</div>
    `;
  }

  // 文字数カウンター
  function setupCharacterCounter(inputId, counterId) {
    const input = container.querySelector(`#${inputId}`);
    const counter = container.querySelector(`#${counterId}`);

    input.addEventListener('input', () => {
      counter.textContent = input.value.length;
    });
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    if (!selectedEquipmentId) {
      errors.push('機器を選択してください');
    }

    const projectSelect = container.querySelector('#project-select');
    if (!projectSelect.value) {
      errors.push('プロジェクトを選択してください');
    }

    const startDateTime = container.querySelector('#start-datetime').value;
    const endDateTime = container.querySelector('#end-datetime').value;

    if (!startDateTime) {
      errors.push('利用開始日時を入力してください');
    }

    if (!endDateTime) {
      errors.push('利用終了日時を入力してください');
    }

    if (startDateTime && endDateTime) {
      const start = new Date(startDateTime);
      const end = new Date(endDateTime);
      const now = new Date();

      if (start < now) {
        errors.push('開始日時は現在日時以降を設定してください');
      }

      if (end <= start) {
        errors.push('終了日時は開始日時より後に設定してください');
      }
    }

    const purpose = container.querySelector('#purpose').value.trim();
    if (!purpose) {
      errors.push('利用目的を入力してください');
    }

    const experimentDetail = container.querySelector('#experiment-detail').value.trim();
    if (!experimentDetail) {
      errors.push('実験内容詳細を入力してください');
    }

    const measurementReq = container.querySelector('#measurement-requirements').value.trim();
    if (!measurementReq) {
      errors.push('測定要件を入力してください');
    }

    const emergencyContact = container.querySelector('#emergency-contact').value.trim();
    if (!emergencyContact) {
      errors.push('緊急連絡先を入力してください');
    } else if (!/^[0-9]{2,4}-[0-9]{2,4}-[0-9]{3,4}$/.test(emergencyContact)) {
      errors.push('緊急連絡先は正しい形式で入力してください（例：090-1234-5678）');
    }

    return errors;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');

    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功メッセージ表示
  function showSuccess(applicationNumber) {
    const successDiv = container.querySelector('#success-message');
    const numberSpan = container.querySelector('#application-number');
    numberSpan.textContent = applicationNumber;
    successDiv.classList.remove('hidden');

    // フォームリセット
    container.querySelector('#reservation-form').reset();
    selectedEquipmentId = null;
    container.querySelector('#selected-equipment').value = '';
    updateReservationSummary();
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    equipmentData = rows || [];
    renderEquipmentList(equipmentData);
  });

  // プロジェクトデータ読み込み
  window.aivicApi.list(3).then(rows => {
    projectData = rows || [];
    const projectSelect = container.querySelector('#project-select');
    projectSelect.innerHTML = '<option value="">プロジェクトを選択</option>' + 
      projectData.filter(p => p.アクティブフラグ).map(p => 
        `<option value="${p.id}">${p.プロジェクト名}</option>`
      ).join('');
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', () => {
    const keyword = container.querySelector('#equipment-search').value.toLowerCase();
    const category = container.querySelector('#category-filter').value;

    let filteredData = equipmentData;

    if (keyword) {
      filteredData = filteredData.filter(equipment => 
        (equipment.機器名 || '').toLowerCase().includes(keyword) ||
        (equipment.機器説明 || '').toLowerCase().includes(keyword)
      );
    }

    if (category) {
      filteredData = filteredData.filter(equipment => 
        (equipment.機器名 || '').includes(category)
      );
    }

    if (filteredData.length === 0) {
      showError('該当する機器が見つかりません');
    }

    renderEquipmentList(filteredData);
  });

  // 機器選択
  container.addEventListener('click', (e) => {
    const selectBtn = e.target.closest('.select-equipment');
    if (selectBtn) {
      const equipmentId = selectBtn.dataset.id;
      const equipment = equipmentData.find(e => e.id === equipmentId);

      if (!equipment.利用可能フラグ) {
        showError('この機器は現在利用できません');
        return;
      }

      selectedEquipmentId = equipmentId;
      container.querySelector('#selected-equipment').value = equipment.機器名;
      container.querySelector('#selected-equipment-id').value = equipmentId;
      showEquipmentDetail(equipmentId);
      updateReservationSummary();
    }

    const equipmentRow = e.target.closest('.equipment-row');
    if (equipmentRow && !e.target.closest('button')) {
      const equipmentId = equipmentRow.dataset.id;
      showEquipmentDetail(equipmentId);
    }
  });

  // カレンダー操作
  container.querySelector('#prev-month').addEventListener('click', () => {
    currentDate.setMonth(currentDate.getMonth() - 1);
    renderCalendar();
  });

  container.querySelector('#next-month').addEventListener('click', () => {
    currentDate.setMonth(currentDate.getMonth() + 1);
    renderCalendar();
  });

  // 日時変更時のサマリー更新
  container.querySelector('#start-datetime').addEventListener('change', updateReservationSummary);
  container.querySelector('#end-datetime').addEventListener('change', updateReservationSummary);

  // 文字数カウンター設定
  setupCharacterCounter('purpose', 'purpose-count');
  setupCharacterCounter('experiment-detail', 'experiment-count');
  setupCharacterCounter('measurement-requirements', 'measurement-count');
  setupCharacterCounter('technical-specs', 'technical-count');

  // フォーム送信
  container.querySelector('#reservation-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join('\n'));
      return;
    }

    const formData = {
      機器ID: selectedEquipmentId,
      プロジェクトID: container.querySelector('#project-select').value,
      利用開始日時: container.querySelector('#start-datetime').value,
      利用終了日時: container.querySelector('#end-datetime').value,
      利用目的: container.querySelector('#purpose').value.trim(),
      実験内容詳細: container.querySelector('#experiment-detail').value.trim(),
      測定要件: container.querySelector('#measurement-requirements').value.trim(),
      技術仕様要求: container.querySelector('#technical-specs').value.trim(),
      緊急連絡先: container.querySelector('#emergency-contact').value.trim(),
      申請日時: new Date().toISOString(),
      承認状態: 0
    };

    try {
      // 研究目的・実験内容テーブルに保存
      const purposeData = {
        研究目的名: formData.利用目的,
        実験内容詳細: formData.実験内容詳細,
        安全性確認済フラグ: false,
        登録日時: new Date().toISOString(),
        承認状態: 0
      };

      const savedPurpose = await window.aivicApi.save(4, purposeData);
      if (!savedPurpose) {
        showError('システムエラーが発生しました。しばらく時間をおいて再度お試しください。');
        return;
      }

      // 測定要件・技術仕様テーブルに保存
      const requirementData = {
        機器ID: selectedEquipmentId,
        測定項目名: '予約申請',
        技術仕様詳細: formData.技術仕様要求 || formData.測定要件,
        必要スキルレベル: 1,
        事前準備必須フラグ: false
      };

      await window.aivicApi.save(5, requirementData);

      // 申請番号生成
      const applicationNumber = 'REQ-' + Date.now().toString().slice(-8);

      showSuccess(applicationNumber);

    } catch (error) {
      showError('予約申請の送信に失敗しました。再度お試しください。');
    }
  });

  // 初期カレンダー描画
  renderCalendar();
}

